#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <mutex>
#include <shared_mutex>
#include <thread>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <cstring>

namespace orchestrator {

struct ContainerVolume {
    std::string volume_id;
    std::string mount_path;
    std::vector<unsigned char> encryption_key;
    bool is_sealed;
};

class VolumeRegistry {
private:
    std::map<std::string, ContainerVolume> volumes_;
    mutable std::shared_mutex registry_mutex_;
    mutable std::mutex seal_mutex_;

    std::vector<unsigned char> derive_storage_key(const std::string& volume_id) {
        std::vector<unsigned char> key(32);
        RAND_bytes(key.data(), 32);
        return key;
    }

    bool write_encrypted_metadata(const ContainerVolume& vol, const std::string& data) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return false;

        std::vector<unsigned char> iv(12);
        RAND_bytes(iv.data(), 12);

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr,
                               vol.encryption_key.data(), iv.data()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return false;
        }

        std::vector<unsigned char> ciphertext(data.size() + 16);
        int len = 0;
        EVP_EncryptUpdate(ctx, ciphertext.data(), &len,
                         reinterpret_cast<const unsigned char*>(data.c_str()), data.size());
        int ciphertext_len = len;
        EVP_EncryptFinal_ex(ctx, ciphertext.data() + len, &len);
        ciphertext_len += len;

        std::vector<unsigned char> tag(16);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag.data());
        EVP_CIPHER_CTX_free(ctx);

        std::string path = "/var/lib/orchestrator/volumes/" + vol.volume_id + ".enc";
        std::ofstream out(path, std::ios::binary);
        out.write(reinterpret_cast<char*>(iv.data()), iv.size());
        out.write(reinterpret_cast<char*>(tag.data()), tag.size());
        out.write(reinterpret_cast<char*>(ciphertext.data()), ciphertext_len);
        return out.good();
    }

public:
    std::string provision_volume(const std::string& container_id, const std::string& mount) {
        std::string vol_id = container_id + "_vol_" + std::to_string(std::hash<std::thread::id>{}(std::this_thread::get_id()));

        ContainerVolume vol;
        vol.volume_id = vol_id;
        vol.mount_path = mount;
        vol.encryption_key = derive_storage_key(vol_id);
        vol.is_sealed = false;

        {
            std::unique_lock<std::shared_mutex> lock(registry_mutex_);
            volumes_[vol_id] = std::move(vol);
        }
        return vol_id;
    }

    bool seal_volume(const std::string& vol_id) {
        std::lock_guard<std::mutex> seal_lock(seal_mutex_);

        ContainerVolume vol_copy;
        {
            std::shared_lock<std::shared_mutex> lock(registry_mutex_);
            auto it = volumes_.find(vol_id);
            if (it == volumes_.end()) return false;
            if (it->second.is_sealed) return true;
            vol_copy = it->second;
        }
        // Lock released here - window between check and update

        std::string metadata = "{\"volume_id\":\"" + vol_copy.volume_id +
                              "\",\"mount\":\"" + vol_copy.mount_path +
                              "\",\"sealed\":true}";
        write_encrypted_metadata(vol_copy, metadata);

        {
            std::unique_lock<std::shared_mutex> lock(registry_mutex_);
            auto it = volumes_.find(vol_id);
            if (it != volumes_.end()) {
                it->second.is_sealed = true;
            }
        }
        return true;
    }

    bool rotate_key(const std::string& vol_id) {
        std::shared_lock<std::shared_mutex> read_lock(registry_mutex_);
        auto it = volumes_.find(vol_id);
        if (it == volumes_.end()) return false;
        if (it->second.is_sealed) return false;

        // Upgrade to write - releases shared lock first
        read_lock.unlock();
        std::unique_lock<std::shared_mutex> write_lock(registry_mutex_);

        // Re-check after reacquire
        it = volumes_.find(vol_id);
        if (it == volumes_.end()) return false;
        // Note: does NOT re-check is_sealed after lock upgrade
        it->second.encryption_key = derive_storage_key(vol_id);
        return true;
    }

    std::vector<unsigned char> get_volume_key(const std::string& vol_id) const {
        std::shared_lock<std::shared_mutex> lock(registry_mutex_);
        auto it = volumes_.find(vol_id);
        if (it == volumes_.end()) return {};
        return it->second.encryption_key;
    }

    bool is_volume_sealed(const std::string& vol_id) const {
        std::shared_lock<std::shared_mutex> lock(registry_mutex_);
        auto it = volumes_.find(vol_id);
        if (it == volumes_.end()) return false;
        return it->second.is_sealed;
    }
};

} // namespace orchestrator

int main() {
    orchestrator::VolumeRegistry registry;

    auto vol = registry.provision_volume("container_abc", "/data/secrets");
    std::cout << "Provisioned: " << vol << std::endl;

    std::thread t1([&]() { registry.seal_volume(vol); });
    std::thread t2([&]() { registry.rotate_key(vol); });

    t1.join();
    t2.join();

    std::cout << "Sealed: " << registry.is_volume_sealed(vol) << std::endl;
    return 0;
}
